import{_ as d,o as e,c as o,ag as a}from"./chunks/framework.CrXGS008.js";const m=JSON.parse('{"title":"Definições","description":"","frontmatter":{},"headers":[],"relativePath":"pt/repair-station/settings.md","filePath":"pt/repair-station/settings.md"}'),r={name:"pt/repair-station/settings.md"};function s(i,t,c,n,l,p){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="definicoes" tabindex="-1">Definições <a class="header-anchor" href="#definicoes" aria-label="Permalink to &quot;Definições&quot;">​</a></h1><p>Cada definição da Repair Station edita-se no <code>/nay</code>, na página <strong>Repair Station</strong> (scope <code>nay_repair.config</code>). As alterações são guardadas na base de dados e aplicadas a todos os jogadores de uma vez. O <code>config.lua</code> contém valores iniciais opcionais: aplicam-se até uma definição ser alterada no <code>/nay</code>, e <strong>Repor</strong> volta a eles.</p><p>A coluna <strong>No /nay</strong> mostra o nome apresentado no painel. A chave é o nome usado pelo <code>config.lua</code> e pela <a href="/pt/nay-lib/api">API HTTP</a>.</p><h2 id="geral" tabindex="-1">Geral <a class="header-anchor" href="#geral" aria-label="Permalink to &quot;Geral&quot;">​</a></h2><table tabindex="0"><thead><tr><th>No /nay</th><th>Chave</th><th>Tipo</th><th>Predefinição</th><th>Descrição</th></tr></thead><tbody><tr><td>Ativado</td><td><code>Enabled</code></td><td>ligado / desligado</td><td>ligado</td><td>Ativa ou desativa todas as estações.</td></tr><tr><td>Conta de pagamento</td><td><code>Account</code></td><td><code>cash</code>, <code>bank</code> ou <code>cash_then_bank</code></td><td><code>cash_then_bank</code></td><td>Onde o preço é cobrado. <code>cash_then_bank</code> recorre ao banco quando falta dinheiro.</td></tr><tr><td>Descontos por profissão</td><td><code>JobDiscounts</code></td><td>lista, até 32</td><td>nenhum</td><td>Descontos para uma profissão a partir de um grau.</td></tr><tr><td>Tempo de espera (segundos)</td><td><code>CooldownSeconds</code></td><td>segundos, 0 a 3600</td><td>0</td><td>Espera mínima entre duas reparações do mesmo jogador. 0 desativa.</td></tr></tbody></table><p>As entradas de <strong>Descontos por profissão</strong>:</p><table tabindex="0"><thead><tr><th>No /nay</th><th>Chave</th><th>Tipo</th><th>Descrição</th></tr></thead><tbody><tr><td>Profissão</td><td><code>Job</code></td><td>texto, 1 a 32 caracteres</td><td>Nome da profissão, tal como no seu framework.</td></tr><tr><td>Grau mínimo</td><td><code>MinGrade</code></td><td>número, 0 a 100</td><td>Grau mais baixo que recebe o desconto.</td></tr><tr><td>Desconto (%)</td><td><code>Percent</code></td><td>número, 1 a 100</td><td>Desconto em percentagem. 100 torna a reparação grátis.</td></tr></tbody></table><h2 id="servicos" tabindex="-1">Serviços <a class="header-anchor" href="#servicos" aria-label="Permalink to &quot;Serviços&quot;">​</a></h2><table tabindex="0"><thead><tr><th>No /nay</th><th>Chave</th><th>Tipo</th><th>Predefinição</th><th>Descrição</th></tr></thead><tbody><tr><td>Serviços de reparação</td><td><code>Services</code></td><td>lista, 1 a 8</td><td>Reparação do motor 250 $, Carroçaria e pneus 400 $, Reparação completa 700 $</td><td>Serviços oferecidos em cada estação.</td></tr><tr><td>Preço consoante os danos</td><td><code>PriceByDamage</code></td><td>ligado / desligado</td><td>ligado</td><td>Ajusta o preço aos danos das partes reparadas.</td></tr><tr><td>Preço mínimo (%)</td><td><code>MinPricePercent</code></td><td>número, 0 a 100</td><td>20</td><td>Parte mais baixa do preço do serviço quando o preço acompanha os danos.</td></tr><tr><td>Recusar veículos sem danos</td><td><code>RequireDamage</code></td><td>ligado / desligado</td><td>ligado</td><td>Recusa um serviço quando as partes que repara estão intactas.</td></tr><tr><td>Classes de veículo bloqueadas</td><td><code>BlockedClasses</code></td><td>lista de classes de veículo</td><td>bicicletas, barcos, helicópteros, aviões, comboios</td><td>Classes de veículo recusadas na estação.</td></tr></tbody></table><p>As entradas de <strong>Serviços de reparação</strong>:</p><table tabindex="0"><thead><tr><th>No /nay</th><th>Chave</th><th>Tipo</th><th>Descrição</th></tr></thead><tbody><tr><td>Nome</td><td><code>Label</code></td><td>texto, até 32 caracteres</td><td>Nome mostrado no menu de reparação, no histórico e nos webhooks. Opcional: vazio, o serviço recebe o nome das partes que repara, no idioma do servidor (Reparação do motor, Carroçaria e pneus, Reparação completa...).</td></tr><tr><td>Preço</td><td><code>Price</code></td><td>número, 0 a 1000000</td><td>Preço com danos máximos, antes dos descontos e da percentagem da estação.</td></tr><tr><td>Duração (segundos)</td><td><code>Seconds</code></td><td>número, 3 a 120</td><td>Quanto tempo demora a reparação.</td></tr><tr><td>Repara o motor</td><td><code>Engine</code></td><td>ligado / desligado</td><td>Inclui o depósito.</td></tr><tr><td>Repara a carroçaria</td><td><code>Body</code></td><td>ligado / desligado</td><td>Inclui vidros, portas e deformações.</td></tr><tr><td>Repara os pneus</td><td><code>Tyres</code></td><td>ligado / desligado</td><td>Arranja todos os pneus furados.</td></tr></tbody></table><p>Com <code>PriceByDamage</code> ativado, o preço é o preço do serviço multiplicado pelo maior dano das partes que repara, nunca abaixo de <code>MinPricePercent</code> nem acima de 100 por cento. Depois aplicam-se a percentagem da estação e o desconto por profissão. Desativado, cobra-se sempre o preço completo.</p><p>As entradas de <strong>Classes de veículo bloqueadas</strong> têm um único campo, <strong>Classe</strong> (<code>Class</code>), escolhido pelo nome entre as classes de veículo do GTA.</p><h2 id="stations" tabindex="-1">Estações <a class="header-anchor" href="#stations" aria-label="Permalink to &quot;Estações {#stations}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>No /nay</th><th>Chave</th><th>Tipo</th><th>Predefinição</th><th>Descrição</th></tr></thead><tbody><tr><td>Estações</td><td><code>Stations</code></td><td>lista, até 64</td><td>Hayes Autos, Sandy Shores, Paleto Bay</td><td>As estações. Colocadas com o <a href="/pt/repair-station/stations">editor de estações</a>.</td></tr></tbody></table><p>As entradas editam-se melhor com o <a href="/pt/repair-station/stations">editor de estações</a>, que preenche estes campos por si:</p><table tabindex="0"><thead><tr><th>No /nay</th><th>Chave</th><th>Tipo</th><th>Descrição</th></tr></thead><tbody><tr><td>Identificador</td><td><code>Id</code></td><td>texto, 8</td><td>8 caracteres (0 a 9, a a f), dados pelo editor. Tem de ser único.</td></tr><tr><td>Nome</td><td><code>Label</code></td><td>texto, até 48 caracteres</td><td>Mostrado no aviso, no histórico e nos webhooks. Opcional.</td></tr><tr><td>Aberta</td><td><code>Enabled</code></td><td>ligado / desligado</td><td>Fecha uma estação sem a eliminar.</td></tr><tr><td>Posição do veículo</td><td><code>Coords</code></td><td>posição e direção</td><td>Onde os veículos param, com a direção.</td></tr><tr><td>Raio (m)</td><td><code>Radius</code></td><td>metros, 1,5 a 6</td><td>Distância máxima à posição para um veículo estar na estação.</td></tr><tr><td>Preço (%)</td><td><code>PricePercent</code></td><td>número, 0 a 1000</td><td>Percentagem aplicada a cada preço nesta estação. 100 mantém os preços.</td></tr><tr><td>Modelo do prop</td><td><code>Prop</code></td><td>texto, até 64 caracteres</td><td>Prop colocado junto à estação. Opcional.</td></tr><tr><td>Posição do prop</td><td><code>PropCoords</code></td><td>posição e direção</td><td>Onde está o prop. Opcional.</td></tr><tr><td>Blip do mapa</td><td><code>Blip</code></td><td>ligado / desligado</td><td>Mostra esta estação no mapa.</td></tr></tbody></table><h2 id="mecanicos" tabindex="-1">Mecânicos <a class="header-anchor" href="#mecanicos" aria-label="Permalink to &quot;Mecânicos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>No /nay</th><th>Chave</th><th>Tipo</th><th>Predefinição</th><th>Descrição</th></tr></thead><tbody><tr><td>Profissões de mecânico</td><td><code>MechanicJobs</code></td><td>lista, até 16</td><td><code>mechanic</code></td><td>Profissões contadas como mecânicos em serviço.</td></tr><tr><td>Limite de mecânicos em serviço</td><td><code>MaxMechanicsOnDuty</code></td><td>número, 0 a 64</td><td>0</td><td>As estações fecham enquanto houver este número de mecânicos ou mais em serviço. 0 nunca as fecha.</td></tr></tbody></table><p>As entradas de <strong>Profissões de mecânico</strong>:</p><table tabindex="0"><thead><tr><th>No /nay</th><th>Chave</th><th>Tipo</th><th>Descrição</th></tr></thead><tbody><tr><td>Profissão</td><td><code>Job</code></td><td>texto, 1 a 32 caracteres</td><td>Nome da profissão, tal como no seu framework.</td></tr></tbody></table><h2 id="blips" tabindex="-1">Blips <a class="header-anchor" href="#blips" aria-label="Permalink to &quot;Blips&quot;">​</a></h2><table tabindex="0"><thead><tr><th>No /nay</th><th>Chave</th><th>Tipo</th><th>Predefinição</th><th>Descrição</th></tr></thead><tbody><tr><td>Mostrar blips</td><td><code>ShowBlips</code></td><td>ligado / desligado</td><td>ligado</td><td>Mostra no mapa as estações que têm blip.</td></tr><tr><td>Ícone do blip</td><td><code>BlipSprite</code></td><td>ícone de blip</td><td>446</td><td>Escolhido numa lista visual de ícones. Também é possível escrever qualquer número para um blip personalizado.</td></tr><tr><td>Cor do blip</td><td><code>BlipColor</code></td><td>cor de blip</td><td>47</td><td>Escolhida numa lista visual de cores.</td></tr><tr><td>Tamanho do blip</td><td><code>BlipScale</code></td><td>0,2 a 2</td><td>0,8</td><td>Tamanho do blip.</td></tr></tbody></table>',23)])])}const b=d(r,[["render",s]]);export{m as __pageData,b as default};
